/**
 * The app, in Greek.
 *
 * Keyed on the ENGLISH source string, exactly as the other tables are, because
 * that is what ui() is handed at the call site. One character out and the
 * lookup misses in silence: the app draws the English and nothing anywhere
 * reports a problem.
 *
 * WHO THIS IS FOR. Greek speakers learning German — the course they are doing
 * is German, and this table is the app around it. So it never explains Greek
 * grammar; it only says Save, Next, and Your streak ended.
 *
 * ADDRESS. Εσύ throughout, never εσείς. An app talking to one person who
 * chose to be here, not a form from a public office. Κάτι πήγε στραβά, not
 * Παρουσιάστηκε σφάλμα.
 *
 * NO GENDER ON THE READER. Greek adjectives agree, and this app does not know
 * who is reading it. Every line that would have needed έτοιμος or έτοιμη is
 * written round: a noun, a verb, or an impersonal turn. Where an adjective
 * does agree, it agrees with a thing in the sentence, not with the person.
 *
 * MONOTONIC, and guillemets « » for quotation, both as Greek prints them.
 *
 * GERMAN STAYS GERMAN. The words a lesson teaches — Schultüte, Stau, TÜV,
 * Feierabendbier — are the lesson, so they are left as they are, and so are
 * the app's own name and the handful of proper names (Lucide, Tatoeba,
 * Twemoji) the other tables also carry unchanged.
 */
