  "The exam simulation is the real thing: {count} questions, {minutes} minutes, {pass} to pass.": "Η προσομοίωση εξέτασης είναι το πρωτότυπο: {count} ερωτήσεις, {minutes} λεπτά, {pass} για να περάσεις.",
  "saved": "αποθηκευμένες",
