  "questions": "ερωτήσεις",
  "Star a question during a test to build this.": "Βάλε αστέρι σε μια ερώτηση μέσα στο τεστ, για να χτιστεί αυτή η λίστα.",
  "Nothing wrong yet — take a test first.": "Κανένα λάθος ακόμη — δώσε πρώτα ένα τεστ.",
