  "Local profile": "Τοπικό προφίλ",
  "Picked up where you left off — {n} in.": "Συνέχισε από εκεί που σταμάτησες — {n} μέσα.",
  "That is the missed list cleared. Back to where you were.": "Η λίστα με όσα σου ξέφυγαν άδειασε. Πίσω εκεί που ήσουν.",
  "Back to the start of the list.": "Πίσω στην αρχή της λίστας.",
  "“{item}” marked as known.": "Το «{item}» σημάνθηκε ως γνωστό.",
  "Marked {n} as known.": "{n} σημάνθηκαν ως γνωστά.",
  "“{item}” put off for {days} days.": "Το «{item}» αναβλήθηκε για {days} ημέρες.",
  "Mark “{item}” as known": "Σήμανε το «{item}» ως γνωστό",
