  "Step {step}: {size} pairs, deeper in": "Βήμα {step}: {size} ζευγάρια, πιο βαθιά",
  "Nothing to match yet": "Τίποτα για ταίριασμα ακόμη",
  "Once the course content is loaded, everything you are learning can be matched here.": "Μόλις φορτωθεί το περιεχόμενο του μαθήματος, θα μπορείς να ταιριάζεις εδώ ό,τι μαθαίνεις.",
  "It remembers where you got to, so opening it again carries on rather than starting over — words and sentences each keep their own place, and the list comes back round for review when you reach the end. Tapping a card speaks it, at whatever volume you set for that language. Matching itself changes nothing — both answers are on screen, so it is recognition. Know it and the level menu do write, the same as anywhere else, and keep saying you know them deals bigger boards from further down the queue.": "Θυμάται πού έφτασες, οπότε με το επόμενο άνοιγμα συνεχίζει αντί να ξεκινά από την αρχή — οι λέξεις και οι προτάσεις κρατούν η καθεμία τη δική της θέση, και στο τέλος η λίστα ξαναγυρίζει από την αρχή για επανάληψη. Πατώντας μια κάρτα την ακούς, στην ένταση που έχεις ορίσει για εκείνη τη γλώσσα. Το ίδιο το ταίριασμα δεν αλλάζει τίποτα — και οι δύο απαντήσεις είναι στην οθόνη, άρα πρόκειται για αναγνώριση. Το «Το ξέρω» και το μενού επιπέδου όντως γράφουν, όπως και παντού αλλού, και όσο συνεχίζεις να λες ότι τα ξέρεις, τόσο μεγαλύτερα ταμπλό μοιράζονται από πιο βαθιά μέσα στην ουρά.",
