  "Sound effects control correct and incorrect answer sounds. Voice controls apply to all spoken audio, including lessons, games, and pet speech.": "Ο ρυθμιστής ηχητικών εφέ ελέγχει τους ήχους για σωστές και λάθος απαντήσεις. Οι ρυθμιστές φωνής ισχύουν για κάθε εκφώνηση, και στις ενότητες, και στα παιχνίδια, και στα λόγια του κατοικιδίου.",
  "Read it and say it back": "Διάβασέ το και πες το με δικά σου λόγια",
  "Passages": "Αποσπάσματα",
  "German the way it actually reaches you — messages, notes, a rant about a parcel. Read the whole thing, then put each line into English. Hover any word you do not know; working out the sentence is the part that counts.": "Γερμανικά έτσι όπως σε φτάνουν στ' αλήθεια — μηνύματα, σημειώματα, μια γκρίνια για ένα δέμα. Διάβασε όλο το κείμενο και μετά βάλε κάθε γραμμή στα αγγλικά. Πέρνα τον δείκτη πάνω από όποια λέξη δεν ξέρεις· το να ξεκλειδώσεις την πρόταση είναι η ουσία.",
  "{count} lines": "{count} γραμμές",
  "All passages": "Όλα τα αποσπάσματα",
  "The whole thing, both ways": "Όλο το κείμενο, και στις δύο γλώσσες",
  "You marked {got} of {total} as understood.": "Σημάδεψες {got} από {total} ως κατανοητές.",
  "You wrote": "Έγραψες",
  "Another passage": "Επόμενο απόσπασμα",
  "Hover a word for its meaning": "Πέρνα τον δείκτη πάνω από μια λέξη για τη σημασία της",
  "Put line {number} into English": "Βάλε τη γραμμή {number} στα αγγλικά",
  "Say what it means, in your own words": "Πες τι σημαίνει, με δικά σου λόγια",
  "Compare with the answer": "Σύγκρινε με τη λύση",
  "Show me": "Δείξ' μου",
  "One natural English version": "Μία φυσική αγγλική εκδοχή",
  "That's it — every idea is there.": "Ακριβώς — όλα τα νοήματα είναι εκεί.",
  "Close — one or two ideas short.": "Κοντά — λείπουν ένα δύο νοήματα.",
  "Some of the meaning is missing.": "Λείπει ένα μέρος του νοήματος.",
  "Not in your version: {words}": "Δεν υπάρχουν στη δική σου εκδοχή: {words}",
  "Next line": "Επόμενη γραμμή",
  "I had it after all": "Τελικά το είχα",
  "Your starting point": "Το σημείο εκκίνησής σου",
  "Are you completely new to {language}?": "Ξεκινάς τώρα με τα {language};",
  "Choose the route that fits you. You can change level later.": "Διάλεξε τη διαδρομή που σου ταιριάζει. Μπορείς να αλλάξεις επίπεδο αργότερα.",
  "Yes, start from the beginning": "Ναι, ξεκίνα από την αρχή",
  "Begin with greetings, basic questions, numbers, and everyday phrases.": "Ξεκίνα με χαιρετισμούς, απλές ερωτήσεις, αριθμούς και καθημερινές φράσεις.",
  "No, check my level": "Όχι, έλεγξε το επίπεδό μου",
  "Answer 10 short questions so Micheon can choose a better starting point.": "Απάντησε σε 10 σύντομες ερωτήσεις, ώστε το Micheon να διαλέξει καταλληλότερο σημείο εκκίνησης.",
  "Starting point": "Σημείο εκκίνησης",
  "Recommended module": "Προτεινόμενο τμήμα",
  "Vocabulary check": "Έλεγχος λεξιλογίου",
