  "Which part?": "Ποιο τμήμα;",
  "Point at any part of the app, then click it.": "Δείξε ένα οποιοδήποτε τμήμα της εφαρμογής και κάνε κλικ πάνω του.",
  "Topics you are not interested in": "Θέματα που δεν σε ενδιαφέρουν",
  "These stay in your course and keep any progress — they are simply learned last, after everything else, in lessons and in Listen.": "Αυτά μένουν στο μάθημά σου και κρατούν όποια πρόοδο έχουν — απλώς μαθαίνονται τελευταία, μετά από όλα τα άλλα, και στις ενότητες και στην Ακρόαση.",
  "Give {topic} its normal place in the order again.": "Δώσε ξανά στο {topic} τη φυσιολογική του θέση στη σειρά.",
  "Search topics, like cooking or football…": "Ψάξε θέματα, π.χ. μαγειρική ή ποδόσφαιρο…",
  "Loading your lessons…": "Οι ενότητές σου φορτώνουν…",
  "The stages in a lesson": "Τα βήματα μιας ενότητας",
  "Recommended picks the stages for each phrase: short when you pass the typing test, longer when you miss it. Or set them yourself, and how many times each one runs.": "Το «Προτεινόμενο» διαλέγει τα βήματα για κάθε φράση: λίγα όταν περνάς το τεστ πληκτρολόγησης, περισσότερα όταν το χάνεις. Ή όρισέ τα εσύ — και πόσες φορές τρέχει το καθένα.",
  "1 step for each new phrase": "1 βήμα για κάθε νέα φράση",
  "{count} steps for each new phrase": "{count} βήματα για κάθε νέα φράση",
