  "Run {stage} more times": "Επανάλαβε το {stage} περισσότερες φορές",
  "A phrase you already know still gets one quick recall, a single word skips the stages only a sentence can do, and a stage that needs sound is swapped out while the sound is off.": "Μια φράση που ήδη ξέρεις παίρνει και πάλι μία γρήγορη ανάκληση, μια μεμονωμένη λέξη προσπερνά τα βήματα που μόνο μια πρόταση μπορεί να κάνει, και ένα βήμα που χρειάζεται ήχο αντικαθίσταται όσο ο ήχος είναι κλειστός.",
  "Tap a word to hear it": "Πάτα μια λέξη για να την ακούσεις",
