  "That is why nothing played. Turn it back on?": "Γι' αυτό δεν ακούστηκε τίποτα. Να ξαναενεργοποιηθεί;",
  "Unmute": "Κατάργηση σίγασης",
  "Keep it muted": "Άσ' το σε σίγαση",
