  "Move with ← → and shoot with Space. Hit the right form of the verb. Wrong answer = game over.": "Κινήσου με ← → και πυροβόλησε με το διάστημα. Χτύπα τον σωστό τύπο του ρήματος. Λάθος απάντηση = τέλος παιχνιδιού.",
