  "Vocab Minesweeper": "Ναρκαλιευτής λεξιλογίου",
  "Click a cell and translate the prompt to reveal it safely. Wrong answer = mine.": "Κάνε κλικ σε ένα κελί και μετάφρασε την εκφώνηση για να το ανοίξεις με ασφάλεια. Λάθος απάντηση = νάρκη.",
