  "Click any cell to reveal it. Translate the prompt correctly to defuse it. Wrong answer = boom.": "Κάνε κλικ σε όποιο κελί θες για να το ανοίξεις. Μετάφρασε σωστά την εκφώνηση για να το εξουδετερώσεις. Λάθος απάντηση = μπουμ.",
