  "Click to reveal · Right-click or use Flag mode to mark mines · Translate correctly to defuse": "Κλικ για άνοιγμα · Δεξί κλικ ή λειτουργία σημαίας για να σημαδέψεις νάρκες · Σωστή μετάφραση για εξουδετέρωση",
