  "Find its English match in the arena.": "Βρες το αγγλικό του ταίρι στην αρένα.",
  "Enter the Arena": "Μπες στην αρένα",
  "Read the {meaning} prompt, then steer into its {target} translation. Every correct answer gives you a new phrase. Avoid the wrong choices and enemy snakes.": "Διάβασε την εκφώνηση στα {meaning} και μετά οδήγησε πάνω στη μετάφρασή της στα {target}. Κάθε σωστή απάντηση σου δίνει μια νέα φράση. Απόφυγε τις λάθος επιλογές και τα εχθρικά φίδια.",
  "Master the German articles! Guide your snake to consume words that match your target. Watch out for world boundaries and enemy bots!": "Κατάκτησε τα γερμανικά άρθρα! Οδήγησε το φίδι σου σε λέξεις που ταιριάζουν στον στόχο σου. Πρόσεχε τα όρια του κόσμου και τα εχθρικά μποτ!",
