  "High Score": "Ρεκόρ",
  "How to play": "Πώς παίζεται",
  "Move your mouse to steer. Hold click or Space to boost. Read the {meaning} prompt and collect its {target} translation. Wrong choices cost points; enemy snakes end the run.": "Κίνησε το ποντίκι για να οδηγήσεις. Κράτα πατημένο το κλικ ή το διάστημα για ταχύτητα. Διάβασε την εκφώνηση στα {meaning} και μάζεψε τη μετάφρασή της στα {target}. Οι λάθος επιλογές κοστίζουν πόντους· τα εχθρικά φίδια τερματίζουν την προσπάθεια.",
  "Move your mouse to steer. Hold click or Space to boost speed (costs score). Eat words matching the Target Article to grow. Avoid hitting Bots! If a bot hits your body, you get bonus points.": "Κίνησε το ποντίκι για να οδηγήσεις. Κράτα πατημένο το κλικ ή το διάστημα για ταχύτητα· αυτό κοστίζει πόντους. Φάε λέξεις με το άρθρο-στόχο για να μεγαλώσεις. Απόφυγε τα μποτ! Αν ένα μποτ χτυπήσει το σώμα σου, παίρνεις πόντους μπόνους.",
  "{language} clue": "Ένδειξη στα {language}",
