  "Practice Lv": "Επ. εξάσκησης",
  "Every word, phrase and sentence you can recall — your whole fluency level in one place.": "Κάθε λέξη, φράση και πρόταση που μπορείς να ανακαλέσεις — όλο το επίπεδο ευχέρειάς σου σε ένα σημείο.",
