  "Set both voices together or tune English and German separately. Changes also apply to lessons, games, and the companion.": "Ρύθμισε και τις δύο φωνές μαζί ή προσάρμοσε χωριστά τα αγγλικά και τα γερμανικά. Οι αλλαγές ισχύουν και για τις ενότητες, τα παιχνίδια και τον συνοδό.",
