  "The meaning on a lesson card": "Η σημασία σε μια κάρτα ενότητας",
  "On the card it sits under the sentence at a size you can read at a glance. Underneath keeps it small and out of the way, for practising without it.": "Πάνω στην κάρτα κάθεται κάτω από την πρόταση, σε μέγεθος που διαβάζεται με μια ματιά. Το «από κάτω» την κρατά μικρή και παράμερα, για εξάσκηση χωρίς αυτήν.",
