  "Master": "Γενική",
  "Set both voices together or tune English and German separately.": "Ρύθμισε και τις δύο φωνές μαζί ή προσάρμοσε χωριστά τα αγγλικά και τα γερμανικά.",
  "Cyrillic": "Κυριλλικά",
  "Cyrillic and Latin": "Κυριλλικά και λατινικά",
  "Latin": "Λατινικά",
  "Let small typos through": "Άσε τα μικρά τυπογραφικά να περάσουν",
  "Mark it exactly": "Βαθμολόγησε με ακρίβεια",
  "Exam practice": "Προετοιμασία εξετάσεων",
  "Full forms": "Πλήρεις τύποι",
  "Practise the short, natural forms people use. Full forms stay visible and count as correct.": "Εξασκήσου στους σύντομους, φυσικούς τύπους που χρησιμοποιεί ο κόσμος. Οι πλήρεις τύποι μένουν ορατοί και μετρούν επίσης ως σωστοί.",
  "Practise complete standard forms for formal writing, careful listening, and test answers.": "Εξασκήσου στους πλήρεις κανονικούς τύπους, για επίσημο γράψιμο, προσεκτική ακρόαση και απαντήσεις σε τεστ.",
  "Low": "Σπάνια",
  "Normal": "Κανονικά",
