  "Use": "Χρήση",
  "Medium": "Μεσαία",
  "Close pet": "Κλείσιμο κατοικιδίου",
  "Mute messages & questions": "Σίγαση μηνυμάτων και ερωτήσεων",
  "Show messages & questions": "Εμφάνιση μηνυμάτων και ερωτήσεων",
  "Turn on pet voice": "Ενεργοποίηση φωνής κατοικιδίου",
  "Mute pet voice": "Σίγαση φωνής κατοικιδίου",
  "Drag this header to detach and place it anywhere.": "Σύρε αυτήν τη μπάρα για να αποσπάσεις το παράθυρο και να το βάλεις όπου θες.",
  "You can change answers to earlier questions.": "Μπορείς να αλλάξεις απαντήσεις σε προηγούμενες ερωτήσεις.",
  "No pet messages yet": "Κανένα μήνυμα κατοικιδίου ακόμη",
  "Tips and questions will appear here after the mascot speaks.": "Οι συμβουλές και οι ερωτήσεις θα εμφανίζονται εδώ, αφού μιλήσει η μασκότ.",
  "Yes": "Ναι",
  "No": "Όχι",
  "Let's practise some German.": "Ας εξασκηθούμε λίγο στα γερμανικά.",
  "Los geht's! Let's go.": "Los geht's! Πάμε.",
  "German tip: when a word uses der, die, or das, learn them together — say “der Tisch”, not just “Tisch”.": "Συμβουλή για τα γερμανικά: όταν μια λέξη παίρνει der, die ή das, μάθε τα μαζί — πες «der Tisch», όχι σκέτο «Tisch».",
  "German tip: in a normal German sentence, the verb comes second — “Heute gehe ich nach Hause.”": "Συμβουλή για τα γερμανικά: σε μια κανονική γερμανική πρόταση το ρήμα μπαίνει δεύτερο — «Heute gehe ich nach Hause.»",
  "German tip: after weil or dass, put the verb at the end — “weil ich müde bin”.": "Συμβουλή για τα γερμανικά: μετά το weil ή το dass, το ρήμα πάει στο τέλος — «weil ich müde bin».",
  "German tip: German words for people, places, things, or ideas always start with a capital letter.": "Συμβουλή για τα γερμανικά: οι γερμανικές λέξεις για πρόσωπα, τόπους, πράγματα ή ιδέες ξεκινούν πάντα με κεφαλαίο γράμμα.",
  "German tip: some verbs split in two — “aufstehen” becomes “Ich stehe um sieben auf.”": "Συμβουλή για τα γερμανικά: μερικά ρήματα σπάνε στα δύο — το «aufstehen» γίνεται «Ich stehe um sieben auf.»",
  "English tip: normal sentences usually put who or what first, then the action, then the rest — “I read the book.”": "Συμβουλή για τα αγγλικά: στις κανονικές προτάσεις μπαίνει πρώτα το ποιος ή το τι, μετά η πράξη και μετά τα υπόλοιπα — «I read the book.»",
  "English tip: after can, must, should, or will, use the verb without “to” — “can go”, not “can to go”.": "Συμβουλή για τα αγγλικά: μετά τα can, must, should ή will, το ρήμα μπαίνει χωρίς «to» — «can go», όχι «can to go».",
  "English tip: for habits or facts, verbs with he, she, or it usually end in -s — “she works”, “he knows”.": "Συμβουλή για τα αγγλικά: για συνήθειες ή γεγονότα, τα ρήματα με he, she ή it συνήθως τελειώνουν σε -s — «she works», «he knows».",
  "English tip: describing words normally come before the thing — “a red car”. They stay the same — “a nice man”, “a nice woman”.": "Συμβουλή για τα αγγλικά: οι λέξεις που περιγράφουν μπαίνουν κανονικά πριν από το πράγμα — «a red car». Και δεν αλλάζουν — «a nice man», «a nice woman».",
  "English tip: choose “a” or “an” by sound, not spelling — “a university”, but “an hour”.": "Συμβουλή για τα αγγλικά: διάλεξε «a» ή «an» με βάση τον ήχο, όχι την ορθογραφία — «a university», αλλά «an hour».",
  "English tip: after “didn't”, use go, see, or do — not went, saw, or did: “I didn't go.”": "Συμβουλή για τα αγγλικά: μετά το «didn't» χρησιμοποίησε go, see ή do — όχι went, saw ή did: «I didn't go.»",
  "English tip: “cannot” is one word. Its short form is “can't”.": "Συμβουλή για τα αγγλικά: το «cannot» γράφεται ως μία λέξη. Ο σύντομος τύπος του είναι «can't».",
  "English tip: “will not” becomes “won't”, never “willn't”.": "Συμβουλή για τα αγγλικά: το «will not» γίνεται «won't», ποτέ «willn't».",
  "English tip: German “es gibt” becomes “there is” for one thing and “there are” for several — never “it gives”.": "Συμβουλή για τα αγγλικά: το γερμανικό «es gibt» γίνεται «there is» για ένα πράγμα και «there are» για πολλά — ποτέ «it gives».",
  "English tip: when talking about the past, use “there was” for one thing and “there were” for several.": "Συμβουλή για τα αγγλικά: όταν μιλάς για το παρελθόν, χρησιμοποίησε «there was» για ένα πράγμα και «there were» για πολλά.",
  "English tip: do not use two negatives together — “I didn't see anything”, not “I didn't see nothing”.": "Συμβουλή για τα αγγλικά: μη χρησιμοποιείς δύο αρνήσεις μαζί — «I didn't see anything», όχι «I didn't see nothing».",
  "English tip: “should not” becomes “shouldn't”. The same shortening gives “wouldn't”, “couldn't”, and “mustn't”.": "Συμβουλή για τα αγγλικά: το «should not» γίνεται «shouldn't». Με την ίδια συντόμευση βγαίνουν τα «wouldn't», «couldn't» και «mustn't».",
  "English tip: use “haven't” with I, you, we, or they, and “hasn't” with he, she, or it — “I haven't seen it yet”.": "Συμβουλή για τα αγγλικά: χρησιμοποίησε «haven't» με I, you, we ή they, και «hasn't» με he, she ή it — «I haven't seen it yet».",
