  "Keep this pack in the course, but learn it last — after everything else, in both Continue Learning and Listen.": "Αυτό το πακέτο μένει στο μάθημα, αλλά μαθαίνεται τελευταίο — μετά από όλα τα άλλα, και στο «Συνέχισε τη μάθηση» και στην Ακρόαση.",
