  "Catch the correct letters before they leave the screen.": "Πιάσε τα σωστά γράμματα πριν φύγουν από την οθόνη.",
  "Tap the right letter quickly to train visual recall.": "Πάτα γρήγορα το σωστό γράμμα και γύμνασε την οπτική σου ανάκληση.",
  "Choose the right form of the verb before time runs out.": "Διάλεξε τον σωστό τύπο του ρήματος πριν τελειώσει ο χρόνος.",
  "Steer through tracker words and phrases in your target language.": "Οδήγησε μέσα από λέξεις και φράσεις της καταγραφής σου, στη γλώσσα-στόχο σου.",
  "Catch letters from your tracker without repeating the same small list.": "Πιάσε γράμματα από την καταγραφή σου, χωρίς να επαναλαμβάνεται η ίδια μικρή λίστα.",
  "Tap letters from tracker words and phrases to train visual recall.": "Πάτα γράμματα από λέξεις και φράσεις της καταγραφής και γύμνασε την οπτική σου ανάκληση.",
  "Translate tracker words and phrases to reveal cells safely.": "Μετάφρασε λέξεις και φράσεις της καταγραφής για να ανοίγεις κελιά με ασφάλεια.",
  "Collect tracker words and phrases while keeping the run alive.": "Μάζεψε λέξεις και φράσεις της καταγραφής και κράτα την προσπάθεια ζωντανή.",
  "Eat the word-blocks in order to build the German sentence.": "Φάε τα μπλοκ λέξεων με τη σειρά, για να χτίσεις τη γερμανική πρόταση.",
  "Eat the letters in order to spell the German word.": "Φάε τα γράμματα με τη σειρά, για να γράψεις τη γερμανική λέξη.",
  "E.g. \"Der Apfel\" instead of \"Apfel\"": "Π.χ. «Der Apfel» αντί για «Apfel»",
  "Enter Fullscreen": "Πλήρης οθόνη",
  "Exit Fullscreen": "Έξοδος από πλήρη οθόνη",
  "German:": "Γερμανικά:",
  "Eat the glowing word-blocks in order to build the target sentence. Wrong word = game over.": "Φάε τα φωτεινά μπλοκ λέξεων με τη σειρά, για να χτίσεις την πρόταση-στόχο. Λάθος λέξη = τέλος παιχνιδιού.",
  "Eat the glowing letters in order to spell the target word or phrase. Wrong letter = game over.": "Φάε τα φωτεινά γράμματα με τη σειρά, για να γράψεις τη λέξη ή φράση-στόχο. Λάθος γράμμα = τέλος παιχνιδιού.",
