  "Typing ä, Ä, ö, Ö, ü, Ü and ß on Windows": "Πώς γράφεις ä, Ä, ö, Ö, ü, Ü και ß στα Windows",
  "Learn every Windows numpad code for German letters, then practise the characters in real words and sentences. Includes laptop and no-numpad options.": "Μάθε όλους τους κωδικούς του αριθμητικού πληκτρολογίου των Windows για τα γερμανικά γράμματα και μετά εξασκήσου στους χαρακτήρες μέσα σε αληθινές λέξεις και προτάσεις. Με επιλογές για φορητούς χωρίς αριθμητικό πληκτρολόγιο.",
  "Num Lock on; hold the left Alt key, enter all four digits on the numeric keypad, then release Alt. The number row above the letters will not work. No numpad? Use Micheon's character buttons, or add US-International or UK Extended in Windows.": "Άναψε το Num Lock, κράτα πατημένο το αριστερό Alt, δώσε και τα τέσσερα ψηφία στο αριθμητικό πληκτρολόγιο και μετά άφησε το Alt. Η σειρά αριθμών πάνω από τα γράμματα δεν δουλεύει γι' αυτό. Δεν έχεις αριθμητικό πληκτρολόγιο; Χρησιμοποίησε τα κουμπιά χαρακτήρων του Micheon ή πρόσθεσε στα Windows τη διάταξη US-International ή UK Extended.",
