  "The little words that make you sound natural, not like a textbook.": "Οι μικρές λέξεις που σε κάνουν να ακούγεσαι φυσικά, όχι σαν σχολικό βιβλίο.",
  "Spoken reactions, agreement, and conversational glue.": "Προφορικές αντιδράσεις, συμφωνία και η κόλλα της κουβέντας.",
