  "The one-liners Germans actually shoot back in conversation. Where a phrase is a clip of a fuller sentence, the note shows the full form — so you learn the word order too.": "Οι σύντομες ατάκες που πετούν όντως οι Γερμανοί στην κουβέντα. Όπου μια φράση είναι κομμένη από μια πληρέστερη πρόταση, η σημείωση δείχνει και τον πλήρη τύπο — ώστε να μάθεις και τη σειρά των λέξεων.",
  "React fast and naturally, the way people really talk.": "Αντέδρασε γρήγορα και φυσικά, όπως μιλάει πραγματικά ο κόσμος.",
  "Page": "Σελίδα",
  "is ready": "είναι έτοιμο",
