  "Cards, list rows and settings blocks.": "Κάρτες, γραμμές λίστας και μπλοκ ρυθμίσεων.",
  "Raised background": "Ανυψωμένο φόντο",
  "Hovered rows, inputs and anything sitting on a card.": "Γραμμές κάτω από τον δείκτη, πεδία εισαγωγής και ό,τι κάθεται πάνω σε μια κάρτα.",
  "Lines and outlines": "Γραμμές και περιγράμματα",
