  "Captions, hints and small print.": "Λεζάντες, υποδείξεις και ψιλά γράμματα.",
  "Say": "Πες",
  "That works.": "Αυτό ταιριάζει.",
  "You wanted": "Ζητούμενο ήταν",
  "relative clause": "αναφορική πρόταση",
  "passive": "παθητική φωνή",
  "ihr · a group — you all, not one person": "ihr · μια ομάδα — εσείς όλοι, όχι ένα άτομο",
  "I am learning": "Μαθαίνω",
  "Starts over from the beginning": "Ξεκινά ξανά από την αρχή",
  "Comes back as soon as there is a slot": "Επιστρέφει μόλις υπάρξει θέση",
  "Not confident": "Αβέβαιο",
  "Comes back soon, often within a day": "Επιστρέφει σύντομα, συχνά μέσα σε μία ημέρα",
  "About 3 days away, sooner if you slip": "Σε περίπου 3 ημέρες, νωρίτερα αν κάνεις λάθος",
  "About 10 days away, sooner if you slip": "Σε περίπου 10 ημέρες, νωρίτερα αν κάνεις λάθος",
  "About 30 days away, sooner if you slip": "Σε περίπου 30 ημέρες, νωρίτερα αν κάνεις λάθος",
  "About 180 days away, sooner if you slip": "Σε περίπου 180 ημέρες, νωρίτερα αν κάνεις λάθος",
  "Never comes back at all": "Δεν επιστρέφει ποτέ ξανά",
  "Tomorrow": "Αύριο",
  "In 3 days": "Σε 3 ημέρες",
  "In a week": "Σε μία εβδομάδα",
  "In a month": "Σε έναν μήνα",
  "Nothing brings it back today": "Τίποτα δεν το φέρνει πίσω σήμερα",
  "Held back until then": "Μένει στην άκρη μέχρι τότε",
  "Nothing will show this before then.": "Τίποτα δεν το εμφανίζει πριν από τότε.",
  "Both languages read aloud while you do something else.": "Και οι δύο γλώσσες διαβάζονται δυνατά όσο κάνεις κάτι άλλο.",
  "Right now: {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Αυτήν τη στιγμή: {total} κάρτες τη φορά, η καθεμία ακούγεται {passes}×. Οι πρώτες {total} παίζουν {passes} φορές από την αρχή, μετά οι επόμενες {total} το ίδιο.",
  "Words and sentences": "Λέξεις και προτάσεις",
  "Words only": "Μόνο λέξεις",
  "Sentences and phrases only": "Μόνο προτάσεις και φράσεις",
  "Straight away": "Αμέσως",
  "After 3 more cards": "Μετά από 3 ακόμη κάρτες",
  "After 10 more cards": "Μετά από 10 ακόμη κάρτες",
  "After 30 more cards": "Μετά από 30 ακόμη κάρτες",
  "Three other cards go by first. Short enough that you are still holding the word when it comes back, which is the exercise short-term memory actually is.": "Τρεις άλλες κάρτες περνούν πρώτα. Αρκετά σύντομα ώστε να κρατάς ακόμη τη λέξη όταν επιστρέφει — και αυτή ακριβώς είναι η άσκηση για τη βραχύχρονη μνήμη.",
  "Ten other cards go by first. Far enough that you have to fetch the word back rather than still be carrying it, and near enough to do it several times in one sitting.": "Δέκα άλλες κάρτες περνούν πρώτα. Αρκετά μακριά ώστε να πρέπει να ανασύρεις τη λέξη αντί να τη μεταφέρεις ακόμη μαζί σου, και αρκετά κοντά ώστε να το κάνεις πολλές φορές σε μία συνεδρία.",
  "Thirty other cards go by first. About a session's worth on a narrow filter, so a word returns once you have genuinely moved on from it.": "Τριάντα άλλες κάρτες περνούν πρώτα. Με στενό φίλτρο, περίπου μία ολόκληρη συνεδρία, ώστε μια λέξη να επιστρέφει αφού έχεις πραγματικά προχωρήσει παρακάτω.",
  "After a few hours": "Μετά από λίγες ώρες",
  "After a day": "Μετά από μία ημέρα",
  "When the review says so": "Όταν το λέει η επανάληψη",
  "No wait at all. Anything can play again the moment the order reaches it — which on a narrow filter can mean the same handful of cards all evening. Right for a first pass through a new pack, and not much else.": "Καμία αναμονή. Οτιδήποτε μπορεί να παίξει ξανά μόλις φτάσει εκεί η σειρά — που με στενό φίλτρο σημαίνει την ίδια χούφτα κάρτες όλο το βράδυ. Σωστό για ένα πρώτο πέρασμα σε νέο πακέτο, και για λίγα άλλα.",
  "About four hours. Long enough that you have to remember it rather than recognise it from a minute ago, and short enough to meet it again the same day.": "Περίπου τέσσερις ώρες. Αρκετά πολύ ώστε να πρέπει να το θυμηθείς αντί να το αναγνωρίσεις από πριν ένα λεπτό, και αρκετά λίγο ώστε να το συναντήσεις ξανά την ίδια ημέρα.",
  "A full day. This is the shortest gap the review ladder ever asks for, and the point at which hearing something again is recall rather than an echo.": "Μία ολόκληρη ημέρα. Είναι το πιο μικρό διάστημα που ζητά ποτέ η κλίμακα επανάληψης, και το σημείο όπου το να ακούσεις κάτι ξανά είναι ανάκληση και όχι ηχώ.",
  "Nothing you have answered correctly comes back until the review ladder says it is due — one day, then three, ten, thirty, a hundred and eighty. Anything you have heard but never answered waits a day.": "Ό,τι έχεις απαντήσει σωστά δεν επιστρέφει μέχρι να το ορίσει προς επανάληψη η κλίμακα — μία ημέρα, μετά τρεις, δέκα, τριάντα, εκατόν ογδόντα. Ό,τι έχεις ακούσει αλλά δεν απάντησες ποτέ περιμένει μία ημέρα.",
