  "Twemoji": "Twemoji",
  "The pictures beside the words. Around eight hundred of them ship with the app, so they look the same on every machine and work with no connection.": "Οι εικόνες δίπλα στις λέξεις. Περίπου οκτακόσιες από αυτές έρχονται μαζί με την εφαρμογή, ώστε να φαίνονται ίδιες σε κάθε μηχάνημα και να δουλεύουν χωρίς σύνδεση.",
  "Tatoeba": "Tatoeba",
  "Part of the real-sentence practice. Most of the course is written for Micheon, and the share coming from here falls with every pack that replaces it.": "Ένα μέρος της εξάσκησης με αυθεντικές προτάσεις. Το μεγαλύτερο μέρος του μαθήματος είναι γραμμένο για το Micheon, και το ποσοστό που προέρχεται από εδώ μειώνεται με κάθε πακέτο που το αντικαθιστά.",
