  "What the desktop app is built with.": "Με τι είναι φτιαγμένη η εφαρμογή για υπολογιστή.",
  "Also stay over fullscreen games, watch-only — clicks pass straight through. Some machines still give the game up a frame for anything drawn over it.": "Να μένει και πάνω από παιχνίδια πλήρους οθόνης, μόνο για παρακολούθηση — τα κλικ περνούν κατευθείαν από μέσα. Σε κάποια μηχανήματα το παιχνίδι χάνει ούτως ή άλλως ένα καρέ για ό,τι σχεδιάζεται από πάνω του.",
  "🌱 I'm new to coding": "🌱 Ξεκινάω τώρα με τον προγραμματισμό",
  "colour, practise": "colour, practise",
  "color, practice": "color, practice",
  "A1–A2 · Beginner": "A1–A2 · Αρχάριο επίπεδο",
  "Everyday basics: greetings, ordering, simple questions about yourself.": "Βασικά της καθημερινότητας: χαιρετισμοί, παραγγελίες, απλές ερωτήσεις για σένα.",
  "B1 · Getting by": "B1 · Τα βγάζεις πέρα",
  "Handling ordinary situations alone — appointments, plans, opinions in short.": "Να χειρίζεσαι συνηθισμένες καταστάσεις χωρίς βοήθεια — ραντεβού, σχέδια, σύντομες γνώμες.",
  "B2 · Conversational": "B2 · Άνετα στην κουβέντα",
  "Keeping up with natives on familiar topics, and arguing a point.": "Να συμβαδίζεις με φυσικούς ομιλητές σε γνώριμα θέματα και να υποστηρίζεις μια άποψη.",
