  "Fluent and precise, including work, study and abstract subjects.": "Με ευχέρεια και ακρίβεια, ακόμη και σε εργασία, σπουδές και αφηρημένα θέματα.",
  "C2 · Near-native": "C2 · Σχεδόν μητρική γλώσσα",
  "Anything a native handles: idiom, nuance, humour, fast speech.": "Ό,τι χειρίζεται ένας φυσικός ομιλητής: ιδιωματισμοί, αποχρώσεις, χιούμορ, γρήγορη ομιλία.",
  "All items": "Όλες οι καταχωρίσεις",
