  "Frequency-ranked everyday German, bank ranks 1155–1225.": "Καθημερινά γερμανικά ταξινομημένα κατά συχνότητα, θέσεις 1155–1225 της τράπεζας.",
  "Common words the themed packs never taught, bank ranks 917–1726.": "Συχνές λέξεις που δεν τις δίδαξαν ποτέ τα θεματικά πακέτα, θέσεις 917–1726 της τράπεζας.",
  "Fandom and screen smalltalk: recommending a series without spoilers, binge confessions, the very German dubbing debate, celebrity gossip, and concert hype. \"Welche Serie schaust du gerade?\" has replaced the weather as the default opener.": "Ψιλοκουβέντα για σειρές και για φαν: να προτείνεις μια σειρά χωρίς σπόιλερ, εξομολογήσεις μαραθωνίου, η πολύ γερμανική συζήτηση για τη μεταγλώττιση, κουτσομπολιά για διάσημους και ο πυρετός της συναυλίας. Το «Welche Serie schaust du gerade?» έχει αντικαταστήσει τον καιρό ως αρχή κουβέντας.",
  "Talking about music taste, playing instruments, and German concert & festival culture — from \"Was hörst du so?\" smalltalk to zelten am Gelände, the Zugabe chant, and the Festivalbändchen you never cut off.": "Να μιλάς για μουσικό γούστο, για όργανα που παίζεις και για τη γερμανική κουλτούρα των συναυλιών και των φεστιβάλ — από την ψιλοκουβέντα «Was hörst du so?» ως το zelten am Gelände, τη φωνή για Zugabe και το Festivalbändchen που δεν το κόβεις ποτέ.",
  "The German outdoor rituals: the sacred Sonntagsspaziergang, proper hiking with Brotzeit and a Hütte stop, summer days at the See — and the Deutsche Bahn survival kit for getting there: delays \"mal wieder\", missed Anschlüsse, platform changes and the dreaded Schienenersatzverkehr.": "Τα γερμανικά τελετουργικά του υπαίθρου: ο ιερός Sonntagsspaziergang, η κανονική πεζοπορία με Brotzeit και στάση σε Hütte, οι καλοκαιρινές μέρες στη See — και το κιτ επιβίωσης της Deutsche Bahn για να φτάσεις ως εκεί: καθυστερήσεις «mal wieder», χαμένες Anschlüsse, αλλαγές αποβάθρας και ο φοβερός Schienenersatzverkehr.",
  "Everything a devoted partner actually says in German: the full \"Ich liebe dich\" ladder with its register traps, the pet names Germans really use, missing-you and thinking-of-you lines, heartfelt compliments, and the everyday good-morning/good-night tenderness that carries a relationship.": "Όλα όσα λέει πράγματι στα γερμανικά ένας αφοσιωμένος σύντροφος: ολόκληρη η κλίμακα του «Ich liebe dich» με τις παγίδες ύφους της, τα χαϊδευτικά που χρησιμοποιούν στ' αλήθεια οι Γερμανοί, οι φράσεις του μου λείπεις και του σε σκέφτομαι, τα κομπλιμέντα από καρδιάς και η καθημερινή τρυφερότητα του καλημέρα και του καληνύχτα που κρατά μια σχέση.",
  "Best-friend register: the art of German gossip — lästern is a social sport with strict confidentiality rules (\"Das bleibt unter uns\", \"Kein Wort zu niemandem\") — plus saying what you REALLY think about people, from \"Was ich an ihr mag, ist...\" to the devastating \"Er ist eigentlich ganz nett, aber...\". And the fear chapter: spiders in the bathtub, Höhenangst, Flugangst, nightmares — with the comfort lines (\"Keine Angst, ich bin ja da\") that take the fear away.": "Το ύφος της κολλητής παρέας: η τέχνη του γερμανικού κουτσομπολιού — το lästern είναι κοινωνικό άθλημα με αυστηρούς κανόνες εχεμύθειας («Das bleibt unter uns», «Kein Wort zu niemandem») — μαζί με το να λες τι ΠΡΑΓΜΑΤΙΚΑ σκέφτεσαι για τους ανθρώπους, από το «Was ich an ihr mag, ist...» ως το καταστροφικό «Er ist eigentlich ganz nett, aber...». Και το κεφάλαιο του φόβου: αράχνες στην μπανιέρα, Höhenangst, Flugangst, εφιάλτες — μαζί με τα λόγια παρηγοριάς («Keine Angst, ich bin ja da») που διώχνουν τον φόβο.",
  "The argument survival kit: how Germans actually disagree, hold their ground, blow off steam without getting vulgar — and, most importantly, how they climb back down. Fair-fighting lines, the heated phrases you'll hear (and should recognise as warning signs), and the apology-and-repair language that saves relationships: from \"Es tut mir wirklich leid\" to \"Vertragen wir uns wieder?\".": "Το κιτ επιβίωσης του καβγά: πώς διαφωνούν πράγματι οι Γερμανοί, πώς κρατούν τη θέση τους, πώς ξεσπούν χωρίς να καταφεύγουν σε χυδαιότητες — και, το σημαντικότερο, πώς κατεβάζουν ξανά τους τόνους. Φράσεις για τίμιο καβγά, οι φορτισμένες ατάκες που θα ακούσεις (και που καλά θα κάνεις να τις διαβάζεις ως προειδοποίηση) και η γλώσσα της συγγνώμης και της επανόρθωσης που σώζει σχέσεις: από το «Es tut mir wirklich leid» ως το «Vertragen wir uns wieder?».",
  "The hard territory no phrasebook covers: disclosing trust issues (\"Ich hab Vertrauensprobleme\"), the full cheating vocabulary — fremdgehen vs betrügen, Seitensprung vs Affäre — catching, forgiving (or not), and the eternal men-vs-women discourse from warm \"Typisch Mann!\" banter to serious Gleichberechtigung debates.": "Το δύσκολο έδαφος που δεν το καλύπτει κανένα βιβλίο φράσεων: να μιλάς ανοιχτά για ζητήματα εμπιστοσύνης («Ich hab Vertrauensprobleme»), όλο το λεξιλόγιο της απιστίας — fremdgehen εναντίον betrügen, Seitensprung εναντίον Affäre — το να την ανακαλύπτεις, το να συγχωρείς (ή όχι), και ο αιώνιος λόγος περί αντρών και γυναικών, από το ζεστό πείραγμα «Typisch Mann!» ως τις σοβαρές συζητήσεις για τη Gleichberechtigung.",
  "Frequency-ranked everyday German, bank ranks 1231–1304.": "Καθημερινά γερμανικά ταξινομημένα κατά συχνότητα, θέσεις 1231–1304 της τράπεζας.",
